<script setup lang="ts">
import { computed, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus/es/components/message/index.mjs';
import { usePreview, copy, navigate } from '../../features/preview/usePreviewStore';
import { dateOf } from '../../features/workbench/types';
import PageHeading from '../../features/preview/components/PageHeading.vue';
import Icon from '../../features/workbench/components/WorkbenchIcon.vue';
const props=defineProps<{view:string}>(),s=usePreview();
const tabs=[{id:'shop',name:'店铺接入'},{id:'accounts',name:'客服账号'},{id:'rules',name:'接待规则'},{id:'greeting',name:'自动打招呼'},{id:'retrieval',name:'检索设置'}];
const greeting=reactive(copy(s.greeting)),retrieval=reactive(copy(s.retrieval)),error=ref(''),search=ref('');
const accountOpen=ref(false),accountId=ref<number|null>(null),account=reactive({name:'',login:'',password:'',avatar:''}),accountError=ref('');
const avatarInput=ref<HTMLInputElement|null>(null),avatarBusy=ref(false),scoreError=ref(''),topKError=ref('');
const rows=computed(()=>s.accounts.value.filter(a=>`${a.name} ${a.login}`.includes(search.value.trim())));
function save(){error.value='';scoreError.value='';topKError.value='';if(props.view==='greeting'){if(greeting.enabled&&!greeting.text.trim()){error.value='开启自动打招呼时请填写话术。';return;}Object.assign(s.greeting,copy(greeting));}else if(props.view==='retrieval'){if(!Number.isInteger(retrieval.topK)||retrieval.topK<1||retrieval.topK>10){topKError.value='Top K 请填写 1–10 的整数。';return;}if(!String(retrieval.score).trim()||!Number.isFinite(Number(retrieval.score))||Number(retrieval.score)<0||Number(retrieval.score)>1){scoreError.value='请填写 0–1 之间的数值，例如 0.30。';return;}Object.assign(s.retrieval,{topK:retrieval.topK,score:String(retrieval.score)});}ElMessage.success('设置已保存');}
function openAccount(id?:number){accountId.value=id||null;const a=s.accounts.value.find(a=>a.id===id);Object.assign(account,{name:a?.name||'',login:a?.login||'',password:'',avatar:a?.avatar||''});accountError.value='';accountOpen.value=true;}
function saveAccount(){if(avatarBusy.value)return;accountError.value='';if(!account.name.trim()||!account.login.trim()||(!accountId.value&&account.password.length<6)){accountError.value='请填写客服姓名、登录账号，新账号密码至少 6 位。';return;}if(s.accounts.value.some(a=>a.id!==accountId.value&&a.login===account.login.trim())){accountError.value='登录账号已存在。';return;}if(accountId.value){const a=s.accounts.value.find(a=>a.id===accountId.value)!;a.name=account.name.trim();a.avatar=account.avatar;if(a.id===s.wb.staff.id){s.wb.staff.name=a.name;s.wb.staff.avatar=a.avatar;}}else s.accounts.value.push({id:Date.now(),name:account.name.trim(),login:account.login.trim(),avatar:account.avatar,enabled:true,online:false,lastLogin:''});account.password='';accountOpen.value=false;ElMessage.success('客服资料已保存');}
async function uploadAvatar(event:Event){
 const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024){accountError.value='请选择 2 MB 以内的 JPG、PNG 或 WebP 图片。';return;}
 avatarBusy.value=true;accountError.value='';const target=accountId.value;
 try{const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file);});const image=new Image();image.src=data;await image.decode();if(accountOpen.value&&accountId.value===target)account.avatar=data;}
 catch{accountError.value='图片无法读取，请选择有效的图片文件。';}finally{avatarBusy.value=false;}
}
</script>
<template><div class="pv-page"><PageHeading title="平台设置" description="同一店铺的所有客服共用这些配置。"/><div class="pv-card pv-settings-card"><div class="pv-tabs" role="tablist"><button v-for="t in tabs" :key="t.id" role="tab" :aria-selected="view===t.id" :class="{active:view===t.id}" @click="navigate(`settings/${t.id}`)">{{t.name}}</button></div>
<div v-if="view==='shop'" class="pv-settings-content"><div class="pv-section-intro"><span class="pv-category-symbol"><Icon name="Shop"/></span><div><h3>店铺接入信息</h3><p>一个店铺对应一个租户，共用客服、知识与 AI 配置。</p></div></div><dl class="pv-info-grid"><dt>店铺名称</dt><dd>青禾服饰</dd><dt>电商平台</dt><dd>淘宝</dd><dt>租户标识</dt><dd>qinghe</dd><dt>授权状态</dt><dd><span class="pv-tag amber">待授权</span></dd></dl><div class="pv-notice"><Icon name="InfoFilled"/><span>完成店铺授权后，可同步该店铺的商品、订单与售后信息。</span></div><details class="pv-connection-guide"><summary>查看接入说明</summary><p>请使用店铺授权账号完成平台授权。一个租户对应一个平台和一家店铺；如需变更绑定店铺，请联系平台处理。</p></details></div>
<div v-else-if="view==='accounts'"><div class="pv-filters"><div class="pv-search"><Icon name="Search"/><input v-model="search" placeholder="搜索客服姓名或账号" aria-label="搜索客服"/></div><button class="wb-btn primary pv-filter-end" @click="openAccount()"><Icon name="Plus"/>开通客服账号</button></div><div class="pv-table-scroll"><table class="pv-table"><thead><tr><th>客服</th><th>登录账号</th><th>在线状态</th><th>账号状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td><div class="pv-customer"><span class="wb-avatar blue"><img v-if="a.avatar" :src="a.avatar" :alt="`${a.name}的头像`"/><template v-else>{{a.name.replace('客服','')[0]}}</template></span><strong>{{a.name}} <small v-if="a.id===s.wb.staff.id">当前账号</small></strong></div></td><td>{{a.login}}</td><td><span class="pv-tag" :class="(a.id===s.wb.staff.id?s.wb.staff.online:a.online)&&a.enabled?'green':''">{{(a.id===s.wb.staff.id?s.wb.staff.online:a.online)&&a.enabled?'在线':'离线'}}</span></td><td>{{a.enabled?'正常':'已停用'}}</td><td>{{a.lastLogin?dateOf(a.lastLogin):'尚未登录'}}</td><td><div class="pv-row-actions"><button @click="openAccount(a.id)">编辑</button><button :class="{danger:a.enabled}" @click="a.enabled=!a.enabled;ElMessage.success(a.enabled?'账号已启用':'账号已停用')">{{a.enabled?'停用':'启用'}}</button></div></td></tr></tbody></table><div v-if="!rows.length" class="pv-empty"><strong>没有符合条件的客服</strong></div></div><p class="pv-settings-note">停用后不能接入或回复；手动离线仅影响新会话接入。同一店铺的客服使用相同权限。</p></div>
<div v-else-if="view==='rules'" class="pv-settings-content"><h3>接待规则</h3><p class="pv-muted">以下为系统统一规则，当前版本仅展示，不支持自定义时长。</p><div class="pv-rule-row"><div><strong>人工请求通知</strong><p>向本店所有在线客服展示待接会话，最先接入的客服负责处理。</p></div><span class="pv-tag blue">全员可见 · 先接先得</span></div><div class="pv-rule-row"><div><strong>等待人工安抚</strong><p>超过时长未接入，按知识库中的等待场景回复；客服之后仍可接入。</p></div><strong>300 秒</strong></div><div class="pv-rule-row"><div><strong>AI 会话空闲完结</strong><p>AI 接待阶段，客户长时间没有继续发消息时自动完结。</p></div><strong>5 分钟</strong></div><div class="pv-rule-row"><div><strong>人工会话完结</strong><p>接入后由客服手动完结；完结后客户再次发消息默认回到 AI 接待。</p></div><span class="pv-tag">客服手动处理</span></div><div class="pv-rule-row"><div><strong>客服断线接待</strong><p>检测到客服断线后，由 AI 继续接待客户。</p></div><span class="pv-tag">连接状态检测</span></div></div>
<div v-else-if="view==='greeting'" class="pv-settings-content"><div class="pv-rule-row"><div><h3>自动打招呼</h3><p>客户进入聊天窗口、还没有发送消息时，使用预先配置的话术打招呼。</p></div><el-switch v-model="greeting.enabled" aria-label="自动打招呼"/></div><div class="pv-form pv-settings-form"><label>打招呼话术<textarea v-model="greeting.text" :disabled="!greeting.enabled" rows="4" maxlength="500" aria-label="打招呼话术"/><small>{{greeting.text.length}} / 500 · 固定话术，不调用大模型</small></label></div><div class="pv-greeting-preview"><span class="wb-avatar blue">AI</span><div><strong>AI 客服</strong><p>{{greeting.enabled?greeting.text||'请填写打招呼话术':'自动打招呼已关闭'}}</p></div></div><button class="wb-btn primary" @click="save">保存设置</button></div>
<div v-else class="pv-settings-content"><h3>全店检索设置</h3><p class="pv-muted">统一影响知识召回；分段长度和重叠长度在每篇知识内单独维护。</p><div class="pv-form pv-settings-form"><label>Top K<input v-model.number="retrieval.topK" type="number" min="1" max="10" step="1" aria-label="Top K"/><small>每次最多取回多少个候选片段，默认 5，范围 1–10。</small><span v-if="topKError" class="wb-form-error" role="alert">{{topKError}}</span></label><label>Score（相关性最低分）<input v-model="retrieval.score" type="number" min="0" max="1" step="0.01" :aria-invalid="!!scoreError" aria-describedby="pv-score-help" placeholder="默认 0.30" aria-label="Score" required/><small id="pv-score-help">填写 0–1 之间的数值，默认 0.30。只保留得分达到此值的片段；越高越严格，可能减少召回数量。</small><span v-if="scoreError" class="wb-form-error" role="alert">{{scoreError}}</span></label></div><button class="wb-btn primary" @click="save">保存设置</button></div><p v-if="error" class="wb-form-error pv-settings-error" role="alert">{{error}}</p></div>
<el-dialog v-model="accountOpen" :title="accountId?'编辑客服账号':'开通客服账号'" width="500px" class="wb-dialog" align-center><form id="pv-account-form" class="pv-form" @submit.prevent="saveAccount"><div class="pv-avatar-upload"><span class="wb-avatar blue"><img v-if="account.avatar" :src="account.avatar" alt="客服头像预览"/><template v-else>{{account.name.replace('客服','')[0]||'客'}}</template></span><div><button class="wb-btn" type="button" :disabled="avatarBusy" @click="avatarInput?.click()">{{avatarBusy?'读取图片中':'上传头像'}}</button><button v-if="account.avatar" class="wb-text-button" type="button" @click="account.avatar=''">移除</button><small>JPG、PNG 或 WebP，不超过 2 MB</small></div><input ref="avatarInput" type="file" accept="image/jpeg,image/png,image/webp" hidden @change="uploadAvatar"/></div><label>客服姓名<input v-model="account.name" required maxlength="30"/></label><label>登录账号<input v-model="account.login" :readonly="!!accountId" required maxlength="50"/></label><label>{{accountId?'重置密码（留空不变）':'初始密码'}}<input v-model="account.password" type="password" autocomplete="new-password" :required="!accountId" minlength="6" maxlength="100"/></label><p v-if="accountError" class="wb-form-error" role="alert">{{accountError}}</p></form><template #footer><button class="wb-btn" @click="accountOpen=false">取消</button><button class="wb-btn primary" form="pv-account-form" type="submit" :disabled="avatarBusy">保存账号</button></template></el-dialog>
</div></template>
